const Ctx = createContext<{ lang: Lang; setLang: (l: Lang) => void; t: (k: string) => string }>({ lang: 'en', setLang: () => {}, t: (k) => k });

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>('en');
  useEffect(() => {
    try {
      const s = localStorage.getItem('docbridge-lang');
      if (s === 'hi' || s === 'en') setLangState(s);
    } catch {}
  }, []);
  useEffect(() => {
    try { document.documentElement.lang = lang === 'hi' ? 'hi' : 'en'; } catch {}
  }, [lang]);
  const setLang = useCallback((l: Lang) => {
    setLangState(l);
    try { localStorage.setItem('docbridge-lang', l); } catch {}
  }, []);
  const t = useCallback((k: string) => dict[k]?.[lang] ?? dict[k]?.en ?? k, [lang]);
  return <Ctx.Provider value={{ lang, setLang, t }}>{children}</Ctx.Provider>;
}

export function useLang() {
  return useContext(Ctx);
}

export function LanguageToggle({ compact = false }: { compact?: boolean }) {
  const { lang, setLang } = useLang();
  return (
    <div
      className="inline-flex items-center overflow-hidden rounded-full p-0.5 text-xs font-bold shadow-sm"
      style={{ backgroundColor: '#1E3A8A', border: '1px solid #1E3A8A' }}
      role="group"
      aria-label="Language / भाषा"
    >
      {(['en', 'hi'] as Lang[]).map(l => (
        <button
          key={l}
          type="button"
          onClick={() => setLang(l)}
          aria-pressed={lang === l}
          className={`rounded-full px-2.5 py-1 transition ${lang === l ? '' : 'opacity-80 hover:opacity-100'}`}
          style={lang === l ? { backgroundColor: '#FF9933', color: '#1a1a1a' } : { color: '#ffffff' }}
        >
          {l === 'en' ? 'EN' : 'हिं'}
        </button>
      ))}
    </div>
  );
}

export function voiceLang(lang: Lang): string {
  return lang === 'hi' ? 'hi-IN' : 'en-IN';
}
